118	    /**
119	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
120	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
121	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
122	     */
123	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return onFound.apply(owner);
129	    }
