131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
135	        if (!normalizeAndValidateFields(owner)) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
139	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
140	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
141	        }
142	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
143	        owner.setRegistrationDate(registrationDate);
144	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
145	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
146	        }
147	        owner.setHouseholdId(householdId(owner));
148	        owner.setIdentityKey(identityKey(owner));
149	        if (isDuplicate(owner)) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
153	        if (!sharesHousehold && hasExistingHousehold(owner)) {
154	            return new ResponseEntity<>(HttpStatus.CONFLICT);
155	        }
156	        if (countOwnersInCity(owner.getCity()) >= 50) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        assignRegistrationAttributes(owner, sharesHousehold);
160	        this.clinicService.saveOwner(owner);
161	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
162	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
163	            owner.getMembershipNumber());
164	        HttpHeaders headers = new HttpHeaders();
165	        headers.setLocation(UriComponentsBuilder.newInstance()
166	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
167	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
168	    }
169	
170	    /**
171	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
172	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
173	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
174	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
175	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
176	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
177	     */
178	    private boolean normalizeAndValidateFields(Owner owner) {
179	        if (!normalizeAddressFields(owner)) {
180	            return false;
181	        }
182	        if (owner.getEmail() != null) {
183	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
184	            if (!EMAIL_PATTERN.matcher(email).matches()) {
185	                return false;
186	            }
187	            if (isDisposableEmailDomain(email)) {
188	                return false;
189	            }
190	            owner.setEmail(email);
191	        }
192	        if (!isPostcodeValidForCity(owner)) {
193	            return false;
194	        }
195	        String telephone = normalizeTelephone(owner.getTelephone());
196	        if (telephone == null) {
197	            return false;
198	        }
199	        owner.setTelephone(telephone);
200	        return true;
201	    }
202	
203	    /**
204	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
205	     * returning whether the owner may proceed to creation. The structured fields are preferred when
206	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
207	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
208	     * composed value (the normalized addressLine1, with a single space and the normalized
209	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
210	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
211	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
212	     * address. This is the single place the owner's address is read, canonicalized and written back,
213	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
214	     */
215	    private boolean normalizeAddressFields(Owner owner) {
216	        String line1 = normalizeAddress(owner.getAddressLine1());
217	        if (!line1.isEmpty()) {
218	            String line2 = normalizeAddress(owner.getAddressLine2());
219	            owner.setAddressLine1(line1);
220	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
221	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
222	            return true;
223	        }
224	        String address = normalizeAddress(owner.getAddress());
225	        if (address.isEmpty()) {
226	            return false;
227	        }
228	        owner.setAddress(address);
229	        return true;
230	    }
231	
232	    /**
233	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
234	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
235	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
236	     */
237	    private static boolean isDisposableEmailDomain(String email) {
238	        int at = email.lastIndexOf('@');
239	        if (at < 0) {
240	            return false;
241	        }
242	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
243	    }
244	
245	    /**
246	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
247	     * computed against the owner population rather than carried on the owner itself (currently the
248	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
249	     * listing intentionally omits these flags.
250	     */
251	    private OwnerDto buildOwnerDto(Owner owner) {
252	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
253	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
254	        return ownerDto;
255	    }
