258	    @Override
259	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
260	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
261	        if (currentOwner == null) {
262	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	        }
264	        currentOwner.setAddress(ownerFieldsDto.getAddress());
265	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
266	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
267	        currentOwner.setCity(ownerFieldsDto.getCity());
268	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
269	        currentOwner.setLastName(ownerFieldsDto.getLastName());
270	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
271	        String email = ownerFieldsDto.getEmail();
272	        if (email != null) {
273	            email = email.trim().toLowerCase(Locale.ROOT);
274	            if (!EMAIL_PATTERN.matcher(email).matches()) {
275	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
276	            }
277	        }
278	        currentOwner.setEmail(email);
279	        this.clinicService.saveOwner(currentOwner);
280	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
281	    }
