358	
359	    /** Matches a well-formed postcode: exactly 4 digits. */
360	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
361	
362	    /**
363	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
364	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
365	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
366	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
367	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
368	     */
369	    private static boolean isPostcodeValidForCity(Owner owner) {
370	        String postcode = owner.getPostcode();
371	        if (postcode == null) {
372	            return true;
373	        }
374	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
375	            return false;
376	        }
377	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
378	        if (range == null) {
379	            return true;
380	        }
381	        int value = Integer.parseInt(postcode);
382	        return value >= range[0] && value <= range[1];
383	    }
384	
385	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
386	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
387	
388	    /**
389	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
390	     * code are kept when present; otherwise country code '+61' is assumed and a single
391	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
392	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
393	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
394	     * Returns {@code null} when the number cannot form a valid E.164 value.
395	     */
396	    private static String normalizeTelephone(String telephone) {
397	        if (telephone == null) {
398	            return null;
399	        }
400	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
401	        String e164;
402	        if (cleaned.startsWith("+")) {
403	            e164 = cleaned;
404	        } else {
405	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
406	            e164 = "+61" + national;
407	        }
408	        if (!E164_PATTERN.matcher(e164).matches()) {
409	            return null;
410	        }
411	        return hasValidNationalNumberLength(e164) ? e164 : null;
412	    }
413	
414	    /**
415	     * Whether the national number of a well-formed E.164 value has the length required for its
416	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
417	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
418	     */
419	    private static boolean hasValidNationalNumberLength(String e164) {
420	        String countryCode = Owner.countryCodeOf(e164);
421	        if (countryCode == null) {
422	            return true;
423	        }
424	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
425	    }
426	
427	    /**
428	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
429	     * code, membership number, household id, namesake count and household member count. Each is
430	     * derived from the owner's already-normalized fields and the existing owner population, so this
431	     * must run before the owner is saved, while the counts still exclude the owner being created.
432	     *
433	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
434	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
435	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
436	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
437	     */
438	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
439	        owner.setCustomerCode(generateCustomerCode(owner));
440	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
441	        owner.setHouseholdId(householdId(owner));
442	        owner.setNamesakeCount(countNamesakes(owner));
443	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
444	        if (declaredMember) {
445	            owner.setPossibleDuplicate(false);
446	            owner.setPossibleDuplicateOf(null);
447	        } else {
448	            assignPossibleDuplicate(owner);
449	        }
450	    }
451	
452	    /**
453	     * Whether {@code owner} would join an existing household, i.e. some already-registered owner
454	     * resolves to the same {@link #householdId(Owner) householdId} (same last name and postcode).
455	     * Because the household is keyed on (last name, postcode), such a create is a household duplicate
456	     * and is rejected with {@code 409 CONFLICT} unless the request sets {@code sharesHousehold}, in
457	     * which case the owner is created as a declared household member.
458	     */
459	    private boolean hasExistingHousehold(Owner owner) {
460	        return !findHousemates(owner).isEmpty();
461	    }
462	
463	    /**
464	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
465	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
466	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
467	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
468	     * to the matching owner's id. Runs before save, against the existing owner population.
469	     */
470	    private void assignPossibleDuplicate(Owner owner) {
471	        Integer matchId = findPossibleDuplicateOf(owner);
472	        owner.setPossibleDuplicate(matchId != null);
473	        owner.setPossibleDuplicateOf(matchId);
474	    }
475	
476	    /**
477	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
478	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
479	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
480	     * never matches.
481	     */
482	    private Integer findPossibleDuplicateOf(Owner owner) {
483	        String postcode = owner.getPostcode();
484	        if (postcode == null) {
485	            return null;
486	        }
487	        String lastName = normalizeHouseholdField(owner.getLastName());
488	        String telephone = owner.getTelephone();
489	        return this.clinicService.findAllOwners().stream()
490	            .filter(existing -> !existing.isDeleted())
491	            .filter(existing -> existing.getId() != null
492	                && postcode.equals(existing.getPostcode())
493	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
494	                && !telephone.equals(existing.getTelephone()))
495	            .map(Owner::getId)
496	            .min(Integer::compareTo)
497	            .orElse(null);
498	    }
499	
500	    /**
501	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
502	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
503	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
504	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
505	     * region and the (telephone, last name) pair; only when the computed code collides with an
506	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
507	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
508	     */
509	    private String generateCustomerCode(Owner owner) {
510	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
511	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
512	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
513	        String base = owner.getRegion() + "-" + hash8;
514	        return deduplicateCustomerCode(base);
515	    }
516	
517	    /**
518	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
519	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
520	     * {@code n} of 2 or more that yields a code no existing owner carries.
521	     */
522	    private String deduplicateCustomerCode(String base) {
523	        Set<String> existing = this.clinicService.findAllOwners().stream()
524	            .map(Owner::getCustomerCode)
525	            .filter(code -> code != null)
526	            .collect(java.util.stream.Collectors.toSet());
527	        if (!existing.contains(base)) {
528	            return base;
529	        }
530	        int n = 2;
531	        while (existing.contains(base + "-" + n)) {
532	            n++;
533	        }
534	        return base + "-" + n;
535	    }
536	
537	    /**
538	     * The number of existing owners registered in {@code city}, compared case-insensitively
539	     * with collapsed whitespace.
540	     */
541	    private int countOwnersInCity(String city) {
542	        String normalized = normalizeHouseholdField(city);
543	        return (int) this.clinicService.findAllOwners().stream()
544	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
545	            .count();
546	    }
547	
548	    /**
549	     * The effective registration date to store for a new owner: the date supplied on the request
550	     * when present, otherwise the current server date, in either case rolled forward to a business
551	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
552	     * This single point of resolution is what every registration-date-derived value (the stored
553	     * date, the membership number's year segment, the per-day create-limit) is computed from.
554	     */
555	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
556	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
557	        return toBusinessDay(date);
558	    }
559	
560	    /**
561	     * The fixed list of public holidays that a registration date must not fall on. A date landing
562	     * on one of these is rolled forward, exactly as weekends are.
563	     */
564	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
565	        LocalDate.of(2026, 1, 1),
566	        LocalDate.of(2026, 1, 26),
567	        LocalDate.of(2026, 4, 25),
568	        LocalDate.of(2026, 12, 25),
569	        LocalDate.of(2026, 12, 28));
570	
571	    /**
572	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
573	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
574	     * unchanged.
575	     */
576	    private static LocalDate toBusinessDay(LocalDate date) {
577	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
578	                || PUBLIC_HOLIDAYS.contains(date)) {
579	            date = date.plusDays(1);
580	        }
581	        return date;
582	    }
583	
584	    /**
585	     * Build the membership number '<customerCode>-M<YY>' where YY is the
586	     * {@link #membershipYearSegment(LocalDate) fiscal-year segment} of the {@code registrationDate}
587	     * (e.g. 'NSW-1A2B3C4D-M27').
588	     */
589	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
590	        return customerCode + "-M" + membershipYearSegment(registrationDate);
591	    }
592	
593	    /**
594	     * The two-digit year segment stamped into a membership number: the last two digits of the
595	     * fiscal year (starting 1 July) that contains the business-day-adjusted {@code registrationDate},
596	     * zero-padded (e.g. a date of 2026-09-05 falls in fiscal year 2027 -> '27'). Shares the
597	     * fiscal-year rule with {@link Owner#getFiscalYear()} via {@link Owner#fiscalYear(LocalDate)}.
598	     */
599	    private static String membershipYearSegment(LocalDate registrationDate) {
600	        return String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
601	    }
602	
603	    /**
604	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
605	     * last name, compared case-insensitively.
606	     */
607	    private int countNamesakes(Owner owner) {
608	        String firstName = normalizeHouseholdField(owner.getFirstName());
609	        String lastName = normalizeHouseholdField(owner.getLastName());
610	        return (int) this.clinicService.findAllOwners().stream()
611	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
612	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
613	            .count();
614	    }
615	
616	    /**
617	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
618	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
619	     * unusually high daily signup volume.
620	     */
621	    private boolean isBulkSignupWarning() {
622	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
623	    }
624	
625	    /** The number of existing owners whose registration date is {@code date}. */
626	    private int countOwnersRegisteredOn(LocalDate date) {
627	        return (int) this.clinicService.findAllOwners().stream()
628	            .filter(existing -> date.equals(existing.getRegistrationDate()))
629	            .count();
630	    }
631	
632	    /**
633	     * The single derived key all duplicate detection flows through, formed from the owner's
634	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
635	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
636	     * id is derived, so the household segment is empty at that point. Because the telephone is part
637	     * of the key, two owners in the same household with different telephones resolve to different
638	     * keys and are both allowed.
639	     */
640	    private static String identityKey(Owner owner) {
641	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
642	        String email = owner.getEmail() == null ? "" : owner.getEmail();
643	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
644	        return telephone + "|" + email + "|" + household;
645	    }
646	
647	    /**
648	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
649	     * duplicate condition: the previously separate telephone, email and household checks are now all
650	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
651	     * trips it is rejected with {@code 409 CONFLICT}.
652	     */
653	    private boolean isDuplicate(Owner owner) {
654	        String key = owner.getIdentityKey();
655	        return this.clinicService.findAllOwners().stream()
656	            .filter(existing -> !existing.isDeleted())
657	            .map(Owner::getIdentityKey)
658	            .filter(existing -> existing != null)
659	            .anyMatch(key::equals);
660	    }
661	
662	    /** Common street-type abbreviations expanded during address normalization. */
663	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
664	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
665	
666	    /**
667	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
668	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
669	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
670	     * string when {@code address} is null or blank after normalization.
671	     */
672	    private static String normalizeAddress(String address) {
673	        if (address == null) {
674	            return "";
675	        }
676	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
677	        if (collapsed.isEmpty()) {
678	            return "";
679	        }
680	        StringBuilder sb = new StringBuilder(collapsed.length());
681	        for (String token : collapsed.split(" ")) {
682	            if (sb.length() > 0) {
683	                sb.append(' ');
684	            }
685	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
686	        }
687	        return sb.toString();
688	    }
689	
690	    /**
691	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
692	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
693	     */
694	    private static String normalizeHouseholdField(String value) {
695	        if (value == null) {
696	            return "";
697	        }
698	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
699	    }
700	
701	    /**
702	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
703	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
704	     * key rather than re-derived from the underlying fields here, so the household is described in one
705	     * place and every household-keyed value stays consistent with it.
706	     */
707	    private List<Owner> findHousemates(Owner owner) {
708	        String householdId = householdId(owner);
709	        return this.clinicService.findAllOwners().stream()
710	            .filter(existing -> !existing.isDeleted())
711	            .filter(existing -> householdId(existing).equals(householdId))
712	            .toList();
713	    }
714	
715	    /**
716	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
717	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
718	     */
719	    private int countHouseholdMembers(Owner owner) {
720	        return findHousemates(owner).size() + 1;
721	    }
722	
723	    /**
724	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
725	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
726	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
727	     * string standing in for a missing postcode), so housemates always resolve to the same value
728	     * regardless of registration order, and owners sharing a last name and postcode share it
729	     * automatically.
730	     */
731	    private static String householdId(Owner owner) {
732	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
733	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
734	        return sha256Hex(key).substring(0, 12);
735	    }
736	
737	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
738	    private static String sha256Hex(String input) {
739	        try {
740	            byte[] digest = MessageDigest.getInstance("SHA-256")
741	                .digest(input.getBytes(StandardCharsets.UTF_8));
742	            StringBuilder sb = new StringBuilder(digest.length * 2);
743	            for (byte b : digest) {
744	                sb.append(String.format("%02X", b));
745	            }
746	            return sb.toString();
747	        }
748	        catch (NoSuchAlgorithmException e) {
749	            throw new IllegalStateException("SHA-256 not available", e);
750	        }
751	    }
752	}
