     * Records the details of a new pet owner.
     *
     * @param ownerFieldsDto The pet owner (required)
     * @return The pet owner was successfully added. (status code 201)
     *         or Bad request. (status code 400)
     *         or Server error. (status code 500)
     */
    @Operation(
        operationId = "addOwner",
        summary = "Adds a pet owner",
        description = "Records the details of a new pet owner.",
        tags = { "owners" },
        responses = {
            @ApiResponse(responseCode = "201", description = "The pet owner was successfully added.", content = {
                @Content(mediaType = "application/json", schema = @Schema(implementation = OwnerDto.class))
            }),
            @ApiResponse(responseCode = "400", description = "Bad request.", content = {
                @Content(mediaType = "application/json", schema = @Schema(implementation = ProblemDetailDto.class))
